function Get-HookUserPrompt {
    param([string]$Override = '')

    if (-not [string]::IsNullOrWhiteSpace($Override)) {
        return $Override
    }

    $stdinJson = ''
    try {
        $stdinJson = [Console]::In.ReadToEnd()
    }
    catch {
        $stdinJson = ''
    }
    if (-not $stdinJson.Trim()) {
        try {
            $stdinJson = ($input | Out-String)
        }
        catch {
            $stdinJson = ''
        }
    }
    if (-not $stdinJson.Trim()) { return $null }
    try {
        $hookData = $stdinJson | ConvertFrom-Json
        if ($hookData.prompt) { return [string]$hookData.prompt }
        if ($hookData.user_message) { return [string]$hookData.user_message }
        return $null
    }
    catch {
        return $null
    }
}

